import{_ as a,o as i,c as t,a6 as n}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"CSR 的痛点 · 为什么要把渲染搬回服务端","description":"纯客户端渲染(CSR)把「空壳 HTML + 一大包 JS」发给浏览器，首屏白屏、SEO 抓不到、请求瀑布、社交分享没预览——这四个痛点，正是把渲染推回服务端的原因。","frontmatter":{"title":"CSR 的痛点 · 为什么要把渲染搬回服务端","description":"纯客户端渲染(CSR)把「空壳 HTML + 一大包 JS」发给浏览器，首屏白屏、SEO 抓不到、请求瀑布、社交分享没预览——这四个痛点，正是把渲染推回服务端的原因。","source":"https://daiw.org/manual/ssr/csr-pain"},"headers":[],"relativePath":"manual/computer-programming/ssr/csr-pain.md","filePath":"manual/computer-programming/ssr/csr-pain.md"}'),e={name:"manual/computer-programming/ssr/csr-pain.md"};function r(l,s,o,p,h,d){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="csr-的痛点-·-为什么要把渲染搬回服务端" tabindex="-1">CSR 的痛点 · 为什么要把渲染搬回服务端 <a class="header-anchor" href="#csr-的痛点-·-为什么要把渲染搬回服务端" aria-label="Permalink to &quot;CSR 的痛点 · 为什么要把渲染搬回服务端&quot;">​</a></h1><p>纯客户端渲染(CSR)把「空壳 HTML + 一大包 JS」发给浏览器，首屏白屏、SEO 抓不到、请求瀑布、社交分享没预览——这四个痛点，正是把渲染推回服务端的原因。</p><p>要理解 SSR 为什么会「回来」，得先看清它要解决的问题——<strong>纯客户端渲染(CSR)的痛</strong>。</p><p>CSR 是单页应用(SPA)的默认模式：服务器只发一个几乎<strong>空的 HTML 壳</strong>，内容全靠浏览器下载并执行 JavaScript 后<strong>现场画出来</strong>。这个壳长这样：</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;root&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 空的,啥也没有 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/app.bundle.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 全部内容都在这一大包 JS 里 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>浏览器拿到它之后，要走一长串<strong>串行</strong>步骤才能看到内容：</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[&quot;请求页面&quot;] --&gt; B[&quot;拿到空 HTML 壳&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[&quot;下载 JS bundle&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; D[&quot;解析 + 执行 JS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt; E[&quot;发起数据请求&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt; F[&quot;拿到数据&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  F --&gt; G[&quot;渲染出内容&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>问题就藏在这条链里。逐个看。</p><h2 id="痛点一-首屏白屏" tabindex="-1">痛点一：首屏白屏 <a class="header-anchor" href="#痛点一-首屏白屏" aria-label="Permalink to &quot;痛点一：首屏白屏&quot;">​</a></h2><p>从「拿到空壳」到「渲染出内容」之间的每一步，用户看到的都是<strong>一片空白</strong>（或一个转圈）。在这条链走完之前，页面上什么有意义的东西都没有。</p><p>这直接拖垮两个关键指标：<strong>FCP（首次内容绘制）</strong> 和 <strong>LCP（最大内容绘制）</strong>。JS 包越大、网络越慢、设备越差，白屏越久。低端手机上，「下载 + 解析 + 执行」一大包 JS 可能就要好几秒——这几秒里，用户对着白屏，很可能已经走了。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>CSR 的白屏，本质是<strong>把「渲染工作」全压到了用户设备上</strong>。服务器很轻松（只发个静态壳），但代价是每个用户的浏览器都要从零算一遍。你的服务器越省事，用户的首屏就越慢——这笔账，CSR 是让用户来付的。</p></div><h2 id="痛点二-seo-抓不到" tabindex="-1">痛点二：SEO 抓不到 <a class="header-anchor" href="#痛点二-seo-抓不到" aria-label="Permalink to &quot;痛点二：SEO 抓不到&quot;">​</a></h2><p>搜索引擎和社交平台的爬虫来抓你的页面，拿到的是那个<strong>空壳</strong>——<code>&lt;div id=&quot;root&quot;&gt;&lt;/div&gt;</code> 里什么都没有。内容要等 JS 执行完才出现，而很多爬虫<strong>不执行 JS，或执行得不完整、有延迟、有预算限制</strong>。</p><p>结果：你辛辛苦苦写的内容，搜索引擎可能根本没「看见」，自然也就不给你排名。对于内容站、电商、博客这种<strong>靠搜索引流</strong>的站点，CSR 的这个痛点是致命的。</p><h2 id="痛点三-请求瀑布" tabindex="-1">痛点三：请求瀑布 <a class="header-anchor" href="#痛点三-请求瀑布" aria-label="Permalink to &quot;痛点三：请求瀑布&quot;">​</a></h2><p>看回那张流程图，注意它是<strong>一条直线</strong>——每一步都得等上一步做完：</p><p><strong>下载 HTML → 下载 JS → 执行 JS → 才知道要请求哪些数据 → 请求数据 → 渲染。</strong></p><p>数据请求<strong>排在 JS 执行之后</strong>，因为「要请求什么数据」这个信息本身写在 JS 里。于是形成一个<strong>串行瀑布</strong>：该早点开始的数据请求，被硬生生推到了很后面。本可以并行的事被串起来做，首屏就更慢了。</p><h2 id="痛点四-社交分享没预览" tabindex="-1">痛点四：社交分享没预览 <a class="header-anchor" href="#痛点四-社交分享没预览" aria-label="Permalink to &quot;痛点四：社交分享没预览&quot;">​</a></h2><p>把 CSR 页面的链接发到微信、Twitter、Slack，它们的爬虫抓到空壳、读不到 <code>&lt;title&gt;</code> 和 <code>og:</code> 元数据（那些也可能是 JS 动态设置的）——于是<strong>分享出去不成卡片</strong>，只有一个光秃秃的链接。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>这正是<a href="/Front2Full/manual/computer-programming/ssr/what-is-ssr">「元数据决定分享卡片」</a>的现实意义：分享卡片、SEO 摘要，都依赖<strong>初始 HTML 里就有</strong>正确的 <code>&lt;title&gt;</code> / <code>&lt;meta&gt;</code> / <code>og:image</code>。CSR 把这些交给运行时的 JS，爬虫往往等不到。要让链接分享成卡片，内容和元数据必须<strong>在服务端就写进 HTML</strong>——这就指向了 SSR。</p></div><h2 id="痛点五-包体与设备" tabindex="-1">痛点五：包体与设备 <a class="header-anchor" href="#痛点五-包体与设备" aria-label="Permalink to &quot;痛点五：包体与设备&quot;">​</a></h2><p>CSR 把整个应用的渲染逻辑、路由、状态管理全塞进 JS 包。应用越大，包越大；包越大，「下载 + 解析 + 执行」越久。而这笔开销<strong>每个用户、每次首次访问都要付一遍</strong>，且在低端设备上被放大——CPU 弱，解析执行 JS 就慢。你在高端开发机上体验流畅，不代表用户的千元机上也流畅。</p><h2 id="csr-也不是一无是处" tabindex="-1">CSR 也不是一无是处 <a class="header-anchor" href="#csr-也不是一无是处" aria-label="Permalink to &quot;CSR 也不是一无是处&quot;">​</a></h2><p>得公平地说：CSR 有它的主场。<strong>登录后的后台、仪表盘、内部工具</strong>——这些页面 SEO 无关紧要、用户会长时间停留（首屏那点慢一次就摊平了）、交互极其频繁——CSR 的「一次加载、之后全在客户端流畅切换」反而很香。<strong>CSR 的问题不在于它错，而在于它被用错了地方</strong>：拿它去做面向公众、靠搜索引流、首屏敏感的内容站，就是灾难。</p><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>CSR 把渲染全压到客户端，换来了「一次加载后交互流畅」，却付出了<strong>首屏白屏、SEO 抓不到、请求瀑布、分享无预览</strong>的代价。这些痛点有一个共同的解法：<strong>让服务器把带内容的 HTML 直接发出来</strong>——这就是 SSR。</p><p>下一章，我们就看这件事到底怎么做：一次请求打到服务器后，SSR 在服务端走了怎样一段旅程，才把一份「开箱即用」的 HTML 交到浏览器手里。👉 <a href="/Front2Full/manual/computer-programming/ssr/what-is-ssr">SSR 是什么：一次请求的服务端旅程</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] web.dev.「Rendering on the Web.」<a href="https://web.dev/articles/rendering-on-the-web" target="_blank" rel="noreferrer">https://web.dev/articles/rendering-on-the-web</a> —— CSR / SSR / SSG 的权威对比。</li><li>[2] MDN.「Core Web Vitals / LCP.」<a href="https://developer.mozilla.org/en-US/docs/Web/Performance" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Web/Performance</a> —— FCP、LCP 等指标定义。</li><li>[3] Google Search Central.「JavaScript SEO Basics.」<a href="https://developers.google.com/search/docs/crawling-indexing/javascript/javascript-seo-basics" target="_blank" rel="noreferrer">https://developers.google.com/search/docs/crawling-indexing/javascript/javascript-seo-basics</a> —— 爬虫对 JS 渲染内容的处理。</li></ul>`,31)])])}const k=a(e,[["render",r]]);export{g as __pageData,k as default};
